<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$pageTitle='Reservations';$basePath='../';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('UPDATE reservations SET status=?,note=? WHERE id=?')->execute([$_POST['status'],trim($_POST['note']??''),(int)$_POST['id']]);audit($pdo,'Updated reservation','Reservation #'.(int)$_POST['id'].' '.$_POST['status']);flash('success','Reservation updated.');redirect('reservations.php');}$rows=$pdo->query('SELECT r.*,m.name member_name,b.title FROM reservations r JOIN members m ON m.id=r.member_id JOIN books b ON b.id=r.book_id ORDER BY r.id DESC')->fetchAll();require __DIR__.'/../includes/layout_top.php';?><div class="panel"><h3>Book reservation requests</h3><p class="muted">Members can request a reservation. Approval does not issue the book; issue it separately from Issue / Return.</p><div class="table-wrap"><table><thead><tr><th>Member</th><th>Book</th><th>Requested</th><th>Status</th><th>Decision</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['member_name'])?></td><td><?=e($r['title'])?></td><td><?=e($r['request_date'])?></td><td><span class="pill neutral"><?=e($r['status'])?></span></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach(['pending','approved','rejected','fulfilled','cancelled'] as $st):?><option <?=$r['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><input name="note" placeholder="Note" value="<?=e($r['note'])?>"><button class="btn small">Update</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">No reservation requests.</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/layout_bottom.php';?>
